//! The « À propos » screen (SPEC §9; `docs/design/interface.md`, "M10: About and distribution"):
//! the version, the licence of Ardoise and the components it is built with. The texts are the
//! repository's own `LICENSE` and `THIRD-PARTY-NOTICES` (the latter generated by
//! `cargo xtask licenses --write` and checked by `cargo xtask check`), embedded in the
//! executable: the component list is read back from the notices' lists, so the two cannot
//! disagree. Cisco's notice and the state of OpenH264 come from `codec.rs`.

use serde::Serialize;

use crate::commands::{CommandError, CommandResult};

/// The licence of Ardoise, as the repository's `LICENSE` file.
const LICENSE: &str = include_str!("../../../LICENSE");
/// Every third-party component with its licence texts.
const NOTICES: &str = include_str!("../../../THIRD-PARTY-NOTICES");
/// The SPDX identifier of Ardoise's licence (`license` of the workspace manifest).
const LICENSE_ID: &str = "GPL-3.0-or-later";

/// `AboutComponent` in `about.ts`.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct AboutComponent {
    pub name: String,
    pub version: String,
    /// SPDX expression, as the package declares it.
    pub license: String,
    /// `rust` (compiled into the executable) or `npm` (bundled into the interface).
    pub kind: &'static str,
}

/// `AboutInfo` in `about.ts`.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct AboutInfo {
    pub version: &'static str,
    pub license: &'static str,
    pub components: Vec<AboutComponent>,
}

/// Text with LF line endings (git may check the files out with CRLF on Windows).
fn lf(text: &str) -> String {
    text.replace("\r\n", "\n")
}

/// The package lists of the notices: the lines `name version | licence | repository` after the
/// headings "3. Rust packages" and "4. JavaScript packages", up to the next heading.
fn parse_components(notices: &str) -> Vec<AboutComponent> {
    let mut kind = None;
    let mut components = Vec::new();
    for line in notices.lines() {
        let line = line.trim_end();
        if line.starts_with("3. Rust packages") {
            kind = Some("rust");
        } else if line.starts_with("4. JavaScript packages") {
            kind = Some("npm");
        } else if line.starts_with("5. ") {
            break;
        }
        let Some(kind) = kind else { continue };
        let mut fields = line.splitn(3, " | ");
        let (Some(label), Some(license)) = (fields.next(), fields.next()) else {
            continue;
        };
        // The column header ("name version | licence | repository") is not a package.
        let Some((name, version)) = label.rsplit_once(' ') else {
            continue;
        };
        if version == "version" {
            continue;
        }
        components.push(AboutComponent {
            name: name.to_owned(),
            version: version.to_owned(),
            license: license.to_owned(),
            kind,
        });
    }
    components
}

fn info_of(notices: &str) -> AboutInfo {
    AboutInfo {
        version: env!("CARGO_PKG_VERSION"),
        license: LICENSE_ID,
        components: parse_components(notices),
    }
}

/// The text `which` names: `license` (the GPL) or `notices` (the third-party notices).
fn text_of(which: &str) -> CommandResult<String> {
    match which {
        "license" => Ok(lf(LICENSE)),
        "notices" => Ok(lf(NOTICES)),
        other => Err(CommandError::new(
            "unexpected",
            format!("no such text: {other}"),
        )),
    }
}

#[tauri::command]
pub fn about_info() -> CommandResult<AboutInfo> {
    Ok(info_of(&lf(NOTICES)))
}

#[tauri::command]
pub fn about_text(which: String) -> CommandResult<String> {
    text_of(&which)
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = "THIRD-PARTY NOTICES\r\n1. Tuhi\r\nfoo | bar | baz\r\n3. Rust packages: 2\r\n------\r\n\r\nname version | licence | repository\r\n\r\nserde 1.0.229 | MIT OR Apache-2.0 | https://github.com/serde-rs/serde\r\nzeta 0.1.0-beta.2 | MPL-2.0 | -\r\n\r\n4. JavaScript packages (interface bundle): 1\r\n------\r\n\r\nname version | licence | repository\r\n\r\n@scope/pkg 2.0.0 | ISC | -\r\n\r\n5. Licence texts: 1\r\nx | y | z\r\n";

    #[test]
    fn reads_the_two_package_lists_and_nothing_else() {
        let components = parse_components(&lf(SAMPLE));
        let shown: Vec<_> = components
            .iter()
            .map(|c| format!("{} {} {} {}", c.kind, c.name, c.version, c.license))
            .collect();
        assert_eq!(
            shown,
            [
                "rust serde 1.0.229 MIT OR Apache-2.0",
                "rust zeta 0.1.0-beta.2 MPL-2.0",
                "npm @scope/pkg 2.0.0 ISC",
            ]
        );
    }

    #[test]
    fn the_embedded_notices_list_every_component_they_announce() {
        let notices = lf(NOTICES);
        let announced = |heading: &str| -> usize {
            notices
                .lines()
                .find_map(|l| l.strip_prefix(heading))
                .and_then(|rest| rest.rsplit(": ").next())
                .and_then(|n| n.trim().parse().ok())
                .expect("heading with a count")
        };
        let info = info_of(&notices);
        let count = |kind: &str| info.components.iter().filter(|c| c.kind == kind).count();
        assert_eq!(count("rust"), announced("3. Rust packages"));
        assert_eq!(count("npm"), announced("4. JavaScript packages"));
        assert!(
            info.components
                .iter()
                .all(|c| !c.name.is_empty() && !c.version.is_empty() && !c.license.is_empty())
        );
        assert!(info.components.iter().any(|c| c.name == "tauri"));
        assert!(info.components.iter().any(|c| c.name == "svelte"));
    }

    #[test]
    fn the_version_and_licence_are_those_of_the_manifest() {
        let info = about_info().expect("info");
        assert_eq!(info.version, env!("CARGO_PKG_VERSION"));
        assert_eq!(info.license, env!("CARGO_PKG_LICENSE"));
    }

    #[test]
    fn the_texts_are_the_repository_files_with_lf_endings() {
        let license = text_of("license").expect("licence");
        assert!(license.contains("GNU GENERAL PUBLIC LICENSE"));
        assert!(license.contains("Version 3, 29 June 2007"));
        let notices = text_of("notices").expect("notices");
        assert!(notices.starts_with("THIRD-PARTY NOTICES"));
        assert!(notices.contains("Tuhi"));
        assert!(notices.contains("OpenH264 Video Codec provided by Cisco Systems, Inc."));
        assert!(!license.contains('\r') && !notices.contains('\r'));
    }

    #[test]
    fn an_unknown_text_is_a_coded_error() {
        let error = text_of("secrets").expect_err("unknown text");
        assert_eq!(error.code(), "unexpected");
        assert!(error.parts().1.contains("secrets"));
    }
}
